import { basename } from "node:path";
import { isStringWithLength } from "../../support/typesValidations.js";
import { DocusaurusDocPage } from "../pages/DocusaurusDocPage.js";
import { isNotIndexFile } from "../util/files.js";
export const DocusaurusDocTreePage = class DocusaurusDocTreePage extends DocusaurusDocPage {
    constructor(path, options) {
        super(path, options);
        if (isNotIndexFile(path) &&
            isStringWithLength(this.meta.confluenceShortName)) {
            options?.logger?.warn(`An unnecessary confluence short name has been set for ${basename(path)} that is not an index file. This confluence short name will be ignored.`);
        }
    }
    async visit() {
        return this.meta.syncToConfluence ? [this] : [];
    }
};
